--
-- Table structure for table `pointages`
--

DROP TABLE IF EXISTS `pointages`;
CREATE TABLE IF NOT EXISTS `pointages` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `semaine` varchar(190) COLLATE utf8mb4_unicode_ci NOT NULL,
  `date` date NOT NULL,
  `heure` time NOT NULL,
  `motif` enum('debut','pause','finpause','debutpause','fin') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'debut',
  `planning_id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  PRIMARY KEY (`id`),
  KEY `pointages_planning_id_foreign` (`planning_id`),
  KEY `pointages_user_id_foreign` (`user_id`)
) ENGINE=MyISAM AUTO_INCREMENT=2080 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

